// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint64 t, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.warp(t);
        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() { ok = true; } catch { ok = false; }
        uint flip = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
        // On a successful exact-price play, the pot is drained iff the flip was 0.
        assertTrue(!ok || ((c.pot() == 0) == (flip == 0)));
    }
}
